"""Whole integer, byte-key and name-hash contracts from pinned headers."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='해시 테이블 · 비트 혼합 · 정수 표현',
                     sections=sections, questions=questions))


add('include/linux/jhash.h', 'Jenkins 해시 전체: 세 워드 혼합과 마지막 블록',
    '임의 바이트 키 또는 u32 배열을 32비트 해시로 압축하는 Jenkins 계열 구현입니다.',
    'a,b,c 세 상태에 입력을 더하고 빼기·XOR·회전·더하기로 혼합합니다. 마지막 블록은 별도 final 혼합을 거쳐 c를 반환합니다.',
    '해시가 같다고 키가 같다는 뜻은 아닙니다. 길이 단위와 엔디언을 구분하고 암호학적 무결성이나 충돌 저항성을 보장하는 함수로 사용하지 않습니다.',
    [('전체 파일', 'guard와 Jenkins 원저작·public domain 및 커널 수정 이력 주석, bitops와 unaligned/packed_struct 의존성, 크기·마스크 매크로, mix/final, 초기값, 바이트·워드 배열 함수, 고정 워드 수 helper와 wrapper로 구성됩니다. 함수들은 static inline이며 모듈 등록은 없습니다.'),
     ('버킷 크기와 마스크', 'jhash_size(n)은 u32의 1을 n비트 왼쪽으로 이동해 2^n을 만듭니다. jhash_mask(n)은 2^n-1이며 hash&mask로 해당 크기의 버킷 인덱스를 얻습니다. n은 버킷 개수가 아니라 지수입니다. u32 이동이므로 n32 이상까지 안전하다고 가정하면 안 됩니다.'),
     ('혼합의 두 단계', '__jhash_mix는 4,6,8,16,19,4비트 회전을 사용해 세 u32를 가역적으로 혼합합니다. __jhash_final은 14,11,25,16,4,14,24비트 회전으로 최종 c에 변화를 확산합니다. unsigned의 모듈러 산술을 사용하며 96비트 상태에서 c만 반환하는 전체 해시는 가역 함수가 아닙니다.'),
     ('바이트 입력과 초기값', 'jhash는 a=b=c=0xdeadbeef+length+initval로 시작합니다. length는 바이트 수이고 입력 NUL도 일반 바이트입니다. 길이가 12보다 클 때만 12바이트를 세 CPU 엔디언 u32로 읽어 더하고 mix합니다. 비정렬 읽기 helper를 사용하므로 키 주소가 4바이트 정렬일 필요는 없습니다.'),
     ('마지막 0..12바이트', 'switch의 fallthrough로 남은 바이트를 낮은 위치부터 a,b,c에 넣습니다. 예를 들어 4바이트이면 k3<<24,k2<<16,k1<<8,k0를 a에 더합니다. 1..12바이트는 final을 한 번 호출하지만 길이0이면 호출하지 않고 초기 c를 반환합니다. while 조건이 >=12가 아니라 >12인 이유는 정확히 12바이트도 이 마지막 처리에 맡기기 때문입니다.'),
     ('엔디언과 스트리밍 오해', '전체 블록은 CPU 엔디언으로 읽고 마지막 부분은 명시적 바이트 이동으로 조립합니다. 원문도 결과가 엔디언에 의존한다고 명시합니다. initval에 이전 결과를 줄 수 있지만 길이가 초기 상태에 들어가고 매 호출 final을 하므로 조각별 연쇄 호출이 연결된 전체 입력의 한 번 해시와 같다고 볼 수 없습니다.'),
     ('u32 배열 경로', 'jhash2의 length는 워드 개수입니다. 초기 길이 항은 length<<2이고 세 워드씩 처리하다 남은 1..3개를 switch로 더해 final합니다. length0은 초기값을 반환합니다. u32 배열의 숫자 값과 그 배열의 메모리 바이트 표현을 같은 의미로 취급하면 안 됩니다.'),
     ('고정 길이 wrapper', '__jhash_nwords는 세 인자에 initval을 더한 뒤 final합니다. 공개 3words/2words/1word는 0xdeadbeef와 각각 12/8/4를 초기값에 더하고 없는 워드는 0으로 전달합니다. 따라서 대응하는 1..3워드 jhash2 입력과 같은 초기화·최종화를 수행합니다.'),
     ('CS 연결', '해시 충돌과 키 비교, 2의 거듭제곱 테이블, 회전과 이동의 차이, unsigned wrap, 길이 기반 초기화, 블록·꼬리 분리를 학습합니다. 매크로는 인자를 여러 차례 읽고 수정하므로 단순 u32 변수에 쓰는 내부 용법을 따른다고 이해합니다.')],
    [('jhash_mask(8)의 값과 버킷 개수는?', '255와 256이다', '7과 8이다', '인자8은 지수입니다. 1<<8은256이고 그보다1 작은 마스크가 하위8비트를 선택합니다.'),
     ('길이0의 jhash도 final을 호출하는가?', '아니다. 초기 c를 그대로 반환한다', '그렇다. 모든 호출에서 final을 한 번 실행한다', 'switch의 case0은 추가 작업 없이 break합니다. 따라서 결과는 u32 범위의 JHASH_INITVAL+initval입니다.'),
     ('jhash2에서 length3은 몇 바이트의 워드 데이터를 뜻하는가?', 'u32 세 개, 즉 12바이트다', '3바이트다', 'jhash2의 길이 단위는 u32 개수입니다. 초기화에도 length<<2로 바이트 수를 반영합니다.'),
     ('조각별로 이전 해시를 initval에 넘기면 전체 한 번 해시와 항상 같은가?', '아니다. 길이 초기화와 final 호출 경계가 달라진다', '그렇다. 암묵적인 스트리밍 상태이기 때문이다', '32비트 반환값만 다음 초기값에 넣는 것은 a,b,c와 미처리 바이트 상태를 유지하는 스트리밍 API가 아닙니다.')])

add('include/linux/hash.h', '정수 해시 전체: 곱셈 상위 비트와 포인터 접기',
    '정수·long·포인터에서 빠르게 해시 테이블 인덱스를 만드는 helper입니다.',
    '큰 홀수와 곱한 결과의 상위 비트를 사용합니다. 64비트 입력을 32비트 머신에서 처리할 때는 상·하위 워드를 섞는 별도 경로를 사용합니다.',
    'bits는 결과에 사용할 비트 수입니다. 이 헤더는 인자 범위를 런타임에 검사하지 않으므로 유효한 이동 폭과 32비트 반환형을 고려해야 합니다.',
    [('전체 구성', 'guard와 작성자, asm/types와 compiler 포함, BITS_PER_LONG별 long 매핑, 황금비 계열 상수, 선택적 asm/hash, generic과 arch 선택 매크로, 32/64비트 함수, 두 포인터 helper와 endif로 끝납니다. long 폭이32나64가 아니면 #error입니다.'),
     ('상수와 이름', 'GOLDEN_RATIO_32는0x61C88647, 64는0x61C8864680B583EBull입니다. GOLDEN_RATIO_PRIME이라는 역사적 이름은 실제 소수라는 보장이 아니라고 주석이 설명합니다. 큰 홀수 곱셈과 황금비 계열 상수를 이용한 분산 기법이며 암호 해시는 아닙니다.'),
     ('32비트 경로', '__hash_32_generic은 u32 입력과 상수를 곱해 하위32비트 결과를 반환합니다. hash_32는 이를 32-bits만큼 오른쪽으로 이동합니다. 곱셈의 낮은 비트는 상위 입력 비트의 영향을 받지 않으므로 상위 결과 비트를 선택합니다. bits0이면 32비트 값에32비트 이동이 생기므로 안전한 일반 인자로 볼 수 없습니다.'),
     ('64비트 경로의 차이', '64비트 long 환경은 u64 곱셈 후 64-bits만큼 이동합니다. 32비트 long 환경은 입력 상위32비트를 __hash_32로 혼합하고 하위32비트와 XOR한 다음 hash_32를 적용합니다. 두 방식은 같은 수식을 실행하는 구현이 아니므로 아키텍처를 넘어 같은 해시 값을 보장한다고 해석하지 않습니다. 반환형은 u32입니다.'),
     ('아키텍처 대체', 'CONFIG_HAVE_ARCH_HASH이면 asm/hash.h를 포함합니다. HAVE_ARCH__HASH_32 또는 HAVE_ARCH_HASH_64가 없을 때 generic 이름으로 연결합니다. generic 함수는 lib/test_hash.c에서 아키텍처 구현과 비교할 수 있도록 별도로 남아 있습니다. 원본 주석은 구현 변경 시 관련 HAVE_ARCH 설정과 테스트 의미를 함께 맞추라고 설명합니다.'),
     ('포인터 두 함수', 'hash_ptr는 포인터를 unsigned long으로 바꾸어 hash_long으로 보냅니다. hash32_ptr는 64비트 long일 때 상·하위32비트를 XOR하고 u32로 줄이며 32비트에서는 값만 줄입니다. 주석도 후자는 실질적인 혼합 해시라기보다 fold32_ptr라고 부르는 편이 맞다고 설명합니다.'),
     ('CS 연결', '고정 폭 모듈러 곱셈, 버킷 인덱스, 타입별 경로, 아키텍처 최적화와 참조 구현, 포인터 표현의 한계를 학습합니다. Windows LLP64 사용자 공간의 포인터/long 배치를 이 Linux 계약의 실행 검증으로 대신하지 않습니다.')],
    [('곱셈 해시에서 주로 어느 비트를 선택하는가?', '결과의 상위 비트다', '결과의 하위 비트만 선택한다', '곱셈은 낮은 입력 변화가 위쪽으로 전파되지만 높은 입력 비트가 낮은 결과 비트에 영향을 주지 않으므로 상위 부분을 사용합니다.'),
     ('GOLDEN_RATIO_PRIME이라는 이름은 상수가 소수임을 보장하는가?', '아니다. 역사적으로 남은 이름이다', '그렇다. 이름이 수학적 조건을 보장한다', '헤더 주석은 더 이상 실제 소수가 아니며 이전 소수가 해시 분산에 좋지 않았다고 명시합니다.'),
     ('hash32_ptr도 반드시 곱셈 해시를 하는가?', '아니다. 64비트에서는 상하위 XOR로 접는다', '그렇다. hash_ptr와 항상 같은 함수다', '두 함수는 별도 구현입니다. hash32_ptr는 포인터 표현을32비트로 접는 용도이며 hash_long 호출이 없습니다.')])

add('include/linux/stringhash.h', '이름 해시 전체: 불안정한 해시 계약과 길이 결합',
    '짧은 경로 구성 요소에 맞춘 바이트 문자열 해시 인터페이스입니다.',
    '바이트 단위 경로는 salt를 초기 상태로 삼아 부분 갱신하고 마지막에32비트로 혼합합니다. hash_len은 길이와 해시를 u64의 두 절반에 담습니다.',
    '버전·아키텍처·부팅을 넘어 값이 같다는 보장이 없습니다. 영속 파일 식별자나 악의적 충돌에 강한 인증값으로 사용하지 않습니다.',
    [('전체 파일', 'SPDX와 guard, compiler/types/hash 의존성, 안정성·충돌 관련 계약, 바이트별 초기화·갱신·최종화, full_name_hash 선언, hashlen 매크로 세 개, hashlen_string 선언과 endif로 구성됩니다.'),
     ('명시적인 불안정성', '주석은 커널 버전, 아키텍처뿐 아니라 같은 커널의 다른 부팅에서도 안정성을 보장하지 않는다고 설명합니다. 하드웨어 감지나 의도적 무작위화에 의존할 수 있습니다. 악의적인 입력의 충돌 방어를 위한 함수가 아니라 짧은 pathname component에 최적화되어 있습니다.'),
     ('한 바이트씩 갱신', 'init_name_hash(salt)는 salt를 unsigned long으로 변환합니다. partial_name_hash(c,prevhash)는 (prevhash+(c<<4)+(c>>4))*11입니다. 반환형 폭의 unsigned 산술로 계산합니다. 이 함수 자체는 tolower를 하지 않으므로 대소문자 정규화가 필요하면 호출자가 수행합니다. 예시 주석과 실제 인자 있는 초기화 매크로의 선언을 구분해야 합니다.'),
     ('마지막 혼합', 'end_name_hash는 hash_long(hash,32)를 호출해32비트 결과를 얻습니다. 주석은 상위 비트가 dcache의 테이블 인덱스로 유용하도록 한다고 설명합니다. 중간 상태를 그대로 잘라내는 것과 구분합니다.'),
     ('워드 단위 구현 선택', 'full_name_hash는 salt·문자열 포인터·명시적 길이를 받는 외부 __pure 함수입니다. CONFIG_DCACHE_WORD_ACCESS일 때 워드 단위로 더 빠른 다른 해시를 계산할 수 있고, 아니면 바이트별 경로의 wrapper로 돌아간다는 설명이 있습니다. 이 헤더에는 해당 외부 함수 본문이 없으므로 세부 읽기 알고리즘을 여기서 추측하지 않습니다.'),
     ('hash_len의 표현', 'hashlen_create는 (u64)len<<32와 (u32)hash를 OR합니다. hashlen_hash는 하위32비트, hashlen_len은 오른쪽으로32비트 옮긴 하위32비트를 추출합니다. 예를 들어 길이3·해시0x12345678이면0x0000000312345678입니다. 길이와 해시의 정보 폭은 각각32비트입니다.'),
     ('NUL 종료 API와 CS', 'hashlen_string은 NUL 종료 이름의 길이와 해시를 결합해 반환하는 선언입니다. full_name_hash의 명시적 길이와 입력 계약이 다릅니다. 해시와 동일성, salt와 인증 키의 차이, 비트 필드 포장, 구현 선택에 따른 안정성 계약을 학습합니다.')],
    [('같은 파일 이름의 해시를 부팅 사이에 영구 ID로 믿어도 되는가?', '안 된다. 부팅 사이 안정성도 보장하지 않는다', '된다. 같은 이름은 항상 같은 값이어야 한다', '이 헤더는 부팅·버전·아키텍처에 걸친 값의 안정성을 명시적으로 보장하지 않습니다.'),
     ('hash_len의 상위32비트에는 무엇이 들어가는가?', '문자열 길이다', '문자열 해시다', '생성식은 길이를32비트 왼쪽으로 이동하고 해시의 하위32비트를 OR합니다.'),
     ('partial_name_hash가 자동으로 대소문자를 통일하는가?', '아니다. 호출자가 전달한 숫자 c를 그대로 계산한다', '그렇다. 내부에서 항상 tolower를 호출한다', '함수 본문은 이동·더하기·곱셈뿐입니다. 예시의 tolower는 호출자 쪽 처리입니다.')])
